package com.aistudyassistance.backend.dsa; import java.time.LocalDate; import jakarta.validation.constraints.*; public record DsaRequest(@NotBlank @Size(max=255)String title,@NotBlank String platform,@Pattern(regexp="EASY|MEDIUM|HARD")String difficulty,@NotBlank String topic,@Pattern(regexp="NOT_STARTED|IN_PROGRESS|SOLVED")String status,@Min(0)int timeTakenMinutes,@Pattern(regexp="NOT_REVIEWED|REVIEW_NEEDED|REVIEWED")String revisionStatus,@Size(max=5000)String notes,LocalDate solvedAt){}
